#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

class GTakeMetro {
public:
    static int n, m, s;
    static long long t;

    static void step() {
        int curJump = static_cast<int>(t % n);
        int sign = (s < m) ? 1 : -1;
        s += sign * curJump;
        s %= n;
        if (s < 0) s += n;
        t--;
    }

    static void doLoop() {
        for (int i = 0; i < n; i++) {
            step();
        }
    }

    static void solve(istream& in, ostream& out) {
        in >> n >> m >> s >> t;
        s -= 1;

        while ((t % n) != 0) {
            step();
        }

        vector<long long> lastSeem(n, -1);
        while (t != 0) {
            doLoop();
            if (lastSeem[s] != -1) {
                long long interval = lastSeem[s] - t;
                t %= interval;
                break;
            } else {
                lastSeem[s] = t;
            }
        }
        while (t != 0) {
            step();
        }
        out << s + 1 << "\n";
    }
};

int GTakeMetro::n = 0;
int GTakeMetro::m = 0;
int GTakeMetro::s = 0;
long long GTakeMetro::t = 0;

int main() {
    GTakeMetro::solve(cin, cout);
    return 0;
}

